WITH base AS (SELECT * FROM "toy_cases" WHERE NOT coalesce((upper(area) = 'US RESIDENTS'), false)),
cur AS (SELECT CASE regexp_replace(upper(trim(CAST("area" AS VARCHAR))), '[.]', '', 'g') WHEN 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS' THEN 'NORTHERN MARIANA ISLANDS' ELSE regexp_replace(upper(trim(CAST("area" AS VARCHAR))), '[.]', '', 'g') END AS "state", "year" AS "year", arg_max("ytd", "week") FILTER (WHERE "ytd" IS NOT NULL) AS v, max("week") FILTER (WHERE "ytd" IS NOT NULL) AS v_at, max("week") AS last_at, arg_max(coalesce("ytd_flag", ''), "week") AS last_flag FROM base GROUP BY ALL),
nxt AS (SELECT CASE regexp_replace(upper(trim(CAST("area" AS VARCHAR))), '[.]', '', 'g') WHEN 'COMMONWEALTH OF NORTHERN MARIANA ISLANDS' THEN 'NORTHERN MARIANA ISLANDS' ELSE regexp_replace(upper(trim(CAST("area" AS VARCHAR))), '[.]', '', 'g') END AS "state", "year" - 1 AS "year", arg_max("prior_ytd", "week") FILTER (WHERE "prior_ytd" IS NOT NULL) AS v, max("week") FILTER (WHERE "prior_ytd" IS NOT NULL) AS v_at, max("week") AS last_at, arg_max(coalesce("prior_flag", ''), "week") AS last_flag FROM base GROUP BY ALL)
SELECT c."state", c."year", c.v AS "annual", CASE WHEN c.v IS NULL THEN 'no number published through week ' || c.last_at || CASE WHEN c.last_flag <> '' THEN ' (flag: ' || CASE c.last_flag WHEN '-' THEN '''-'' = no reported cases' WHEN 'U' THEN '''U'' = unavailable' WHEN 'N' THEN '''N'' = not reportable in this jurisdiction' ELSE '''' || c.last_flag || '''' END || ')' ELSE '' END WHEN c.v_at < c.last_at THEN 'incomplete: running total last published at week ' || c.v_at || ' of ' || c.last_at || '; later weeks have no number' || CASE WHEN c.last_flag <> '' THEN ' (flag at week ' || c.last_at || ': ' || CASE c.last_flag WHEN '-' THEN '''-'' = no reported cases' WHEN 'U' THEN '''U'' = unavailable' WHEN 'N' THEN '''N'' = not reportable in this jurisdiction' ELSE '''' || c.last_flag || '''' END || ')' ELSE '' END || ', so this is not the year total' WHEN n.last_at IS NOT NULL THEN 'provisional: as published at year end (through week ' || c.v_at || ')' ELSE 'provisional: running total so far (through week ' || c.v_at || ')' END AS period_status, CASE WHEN c.v_at IS DISTINCT FROM c.last_at THEN nullif(c.last_flag, '') END AS flag, n.v AS restated, CASE WHEN n.last_at IS NULL THEN 'no next-year table yet' WHEN n.v IS NULL THEN 'unverified_restatement: next year''s table has no number for this year' || CASE WHEN n.last_flag <> '' THEN ' (flag: ' || CASE n.last_flag WHEN '-' THEN '''-'' = no reported cases' WHEN 'U' THEN '''U'' = unavailable' WHEN 'N' THEN '''N'' = not reportable in this jurisdiction' ELSE '''' || n.last_flag || '''' END || ')' ELSE '' END ELSE 'unverified_restatement: as published in next year''s table (through week ' || n.v_at || ')' || CASE WHEN n.v_at < c.last_at THEN '; covers weeks 1-' || n.v_at || ' of ' || c.last_at || ' only, not the whole year' ELSE '' END || '; not a final disease count' END AS restated_status, CASE WHEN n.v_at IS DISTINCT FROM n.last_at THEN nullif(n.last_flag, '') END AS restated_flag FROM cur c LEFT JOIN nxt n USING ("state", "year") WHERE c."year" >= ? AND c."year" <= ? ORDER BY ALL
